-- Generated by pc2dbt from mapping m_FL_JS_MARTS_CORE (L3107–4053), target ORDERS (L1185–1198).
-- Lines refer to the PowerCenter XML. FLAG comments mark behaviour copied as-is (decision D1); see flags.md.

with
-- SQ_STG_SUPPLIES2 · Source Qualifier · L3361–3379 · reads STG_SUPPLIES (L1021–1028), which another mapping writes: ref() (decision Q5)
sq_stg_supplies2 as (
    select
        stg_supplies.supply_cost,
        stg_supplies.is_perishable,
        stg_supplies.product_id
    from {{ ref('stg_supplies') }} as stg_supplies
),

-- AGG_SUPPLIES_BY_PRODUCT2 · Aggregator · L3380–3391
agg_supplies_by_product2 as (
    select
        sq_stg_supplies2.product_id,
        sum(sq_stg_supplies2.supply_cost) as supply_cost_per_product
    from sq_stg_supplies2
    group by sq_stg_supplies2.product_id
),

-- SQ_STG_ORDER_ITEMS1 · Source Qualifier · L3345–3360 · reads STG_ORDER_ITEMS (L1039–1043), which another mapping writes: ref() (decision Q5)
sq_stg_order_items1 as (
    select
        stg_order_items.order_item_id,
        stg_order_items.order_id,
        stg_order_items.product_id
    from {{ ref('stg_order_items') }} as stg_order_items
),

-- SQ_STG_PRODUCTS2 · Source Qualifier · L3392–3412 · reads STG_PRODUCTS (L1029–1038), which another mapping writes: ref() (decision Q5)
sq_stg_products2 as (
    select
        stg_products.product_id,
        stg_products.product_price,
        stg_products.is_food_item,
        stg_products.is_drink_item
    from {{ ref('stg_products') }} as stg_products
),

-- JNR_ITEMS_PRODUCTS · Joiner · L3413–3433 · Normal Join
jnr_items_products as (
    select
        master.order_id,
        master.order_item_id,
        detail.product_id,
        detail.product_price,
        detail.is_food_item,
        detail.is_drink_item
    from sq_stg_products2 as detail
    inner join sq_stg_order_items1 as master
        on master.product_id = detail.product_id
),

-- JNR_ITEMS_SUPPLIES · Joiner · L3434–3455 · Master Outer Join
jnr_items_supplies as (
    select
        master.order_id,
        master.order_item_id,
        master.product_id,
        master.product_price,
        master.is_food_item,
        master.is_drink_item,
        detail.supply_cost_per_product
    from agg_supplies_by_product2 as detail
    left join jnr_items_products as master  -- FLAG master_outer L3446: JNR_ITEMS_SUPPLIES is a Master Outer Join: it keeps every row from AGG_SUPPLIES_BY_PRODUCT2 (detail) and only the rows from JNR_ITEMS_PRODUCTS (master) that match; JNR_ITEMS_PRODUCTS rows with no match are dropped
        on master.product_id = detail.product_id
),

-- AGG_ITEMS_BY_ORDER · Aggregator · L3456–3475
agg_items_by_order as (
    select
        jnr_items_supplies.order_id,
        count(*) as items_count,
        sum(jnr_items_supplies.product_price) as order_items_subtotal,
        sum(case when (jnr_items_supplies.supply_cost_per_product is null) then 0 else jnr_items_supplies.supply_cost_per_product end) as order_cost,
        max(jnr_items_supplies.is_food_item) as has_food_items,
        max(jnr_items_supplies.is_drink_item) as has_drink_items
    from jnr_items_supplies
    group by jnr_items_supplies.order_id
),

-- SQ_STG_ORDERS1 · Source Qualifier · L3476–3498 · reads STG_ORDERS (L1044–1055), which another mapping writes: ref() (decision Q5)
sq_stg_orders1 as (
    select
        stg_orders.order_id,
        stg_orders.customer_id,
        stg_orders.location_id,
        stg_orders.ordered_at_day,
        stg_orders.subtotal_cents,
        stg_orders.tax_paid_cents,
        stg_orders.order_total_cents,
        stg_orders.subtotal,
        stg_orders.tax_paid,
        stg_orders.order_total
    from {{ ref('stg_orders') }} as stg_orders
),

-- JNR_ORDERS_ITEMS_AGG · Joiner · L3499–3528 · Master Outer Join
jnr_orders_items_agg as (
    select
        detail.order_id,
        master.customer_id,
        master.location_id,
        master.ordered_at_day,
        master.subtotal_cents,
        master.tax_paid_cents,
        master.order_total_cents,
        master.subtotal,
        master.tax_paid,
        master.order_total,
        detail.items_count,
        detail.order_items_subtotal,
        detail.order_cost,
        detail.has_food_items,
        detail.has_drink_items
    from agg_items_by_order as detail
    left join sq_stg_orders1 as master  -- FLAG master_outer L3519: JNR_ORDERS_ITEMS_AGG is a Master Outer Join: it keeps every row from AGG_ITEMS_BY_ORDER (detail) and only the rows from SQ_STG_ORDERS1 (master) that match; SQ_STG_ORDERS1 rows with no match are dropped
        on master.order_id = detail.order_id
),

-- EXP_ORDERS_CALC · Expression · L3529–3553
exp_orders_calc as (
    select
        jnr_orders_items_agg.order_id,
        jnr_orders_items_agg.customer_id,
        jnr_orders_items_agg.location_id,
        jnr_orders_items_agg.ordered_at_day,
        jnr_orders_items_agg.subtotal_cents / 100 as subtotal_recal,
        jnr_orders_items_agg.tax_paid_cents / 100 as tax_paid_recal,
        jnr_orders_items_agg.order_total_cents / 100 as order_total_recal,
        case when (jnr_orders_items_agg.order_items_subtotal is null) then 0 else jnr_orders_items_agg.order_items_subtotal end as order_items_subtotal_cl,
        case when (jnr_orders_items_agg.order_cost is null) then 0 else jnr_orders_items_agg.order_cost end as order_cost_cl,
        case when (jnr_orders_items_agg.has_food_items is null) then 0 else jnr_orders_items_agg.has_food_items end as has_food_items_cl,
        case when (jnr_orders_items_agg.has_drink_items is null) then 0 else jnr_orders_items_agg.has_drink_items end as has_drink_items_cl
    from jnr_orders_items_agg
),

-- SRT_BY_CUSTOMER · Sorter · L3554–3575 · kept: its order numbers the rows for EXP_CUSTOMER_ORDER_NUM (decision Q12)
srt_by_customer as (
    select
        exp_orders_calc.customer_id,
        exp_orders_calc.location_id,
        exp_orders_calc.ordered_at_day,
        exp_orders_calc.order_id,
        exp_orders_calc.subtotal_recal,
        exp_orders_calc.tax_paid_recal,
        exp_orders_calc.order_total_recal,
        exp_orders_calc.order_items_subtotal_cl,
        exp_orders_calc.order_cost_cl,
        exp_orders_calc.has_food_items_cl,
        exp_orders_calc.has_drink_items_cl,
        row_number() over (
            order by lower(exp_orders_calc.customer_id) asc nulls first,
                     exp_orders_calc.ordered_at_day asc nulls first,
                     lower(exp_orders_calc.order_id) asc nulls first
        ) as sort_position  -- FLAG sort_order L3554: SRT_BY_CUSTOMER is kept only to put rows in order for EXP_CUSTOMER_ORDER_NUM (decisions Q12, Q13): sort keys CUSTOMER_ID, ORDERED_AT_DAY, ORDER_ID; case is ignored (Case Sensitive = NO, L3567), so strings sort by lower(); NULLs sort low (Null Treated Low = YES, L3571)
    from exp_orders_calc
),

-- EXP_CUSTOMER_ORDER_NUM · Expression · L3576–3592
exp_customer_order_num as (
    select
        srt_by_customer.order_id,
        srt_by_customer.customer_id,
        srt_by_customer.location_id,
        srt_by_customer.ordered_at_day,
        srt_by_customer.subtotal_recal as subtotal,
        srt_by_customer.tax_paid_recal as tax_paid,
        srt_by_customer.order_total_recal as order_total,
        srt_by_customer.order_items_subtotal_cl as order_items_subtotal,
        srt_by_customer.order_cost_cl as order_cost,
        srt_by_customer.has_food_items_cl as has_food_items,
        srt_by_customer.has_drink_items_cl as has_drink_items,
        srt_by_customer.sort_position
            - coalesce(max(case when srt_by_customer.customer_id is null then srt_by_customer.sort_position end) over (order by srt_by_customer.sort_position) - 1, 0) as customer_order_number  -- FLAG counter L3589: v_PREV_CUSTOMER_ID is set to this row's CUSTOMER_ID (L3588) before v_ORDER_SEQUENCE compares them, so the comparison is true on every row where CUSTOMER_ID is not NULL: one running number over all rows in SRT_BY_CUSTOMER's order that never restarts per CUSTOMER_ID, back to 1 on a row whose CUSTOMER_ID is NULL
    from srt_by_customer
)

select
    cast(exp_customer_order_num.order_id as varchar) as order_id,
    cast(exp_customer_order_num.customer_id as varchar) as customer_id,
    cast(exp_customer_order_num.location_id as varchar) as location_id,
    cast(exp_customer_order_num.ordered_at_day as timestamp) as ordered_at_day,
    cast(exp_customer_order_num.subtotal as decimal(12,2)) as subtotal,  -- FLAG rounds L3783: SUBTOTAL is computed as SUBTOTAL_CENTS/100 (L3534), a double at run time because high precision is off, and is rounded to 2 decimal places by the target column SUBTOTAL decimal(12,2) (decision Q11)
    cast(exp_customer_order_num.tax_paid as decimal(12,2)) as tax_paid,  -- FLAG rounds L3784: TAX_PAID is computed as TAX_PAID_CENTS/100 (L3535), a double at run time because high precision is off, and is rounded to 2 decimal places by the target column TAX_PAID decimal(12,2) (decision Q11)
    cast(exp_customer_order_num.order_total as decimal(12,2)) as order_total,  -- FLAG rounds L3785: ORDER_TOTAL is computed as ORDER_TOTAL_CENTS/100 (L3536), a double at run time because high precision is off, and is rounded to 2 decimal places by the target column ORDER_TOTAL decimal(12,2) (decision Q11)
    cast(exp_customer_order_num.order_items_subtotal as decimal(12,2)) as order_items_subtotal,
    cast(exp_customer_order_num.order_cost as decimal(12,2)) as order_cost,
    cast(exp_customer_order_num.has_food_items as decimal(1,0)) as has_food_items,
    cast(exp_customer_order_num.has_drink_items as decimal(1,0)) as has_drink_items,
    cast(exp_customer_order_num.customer_order_number as decimal(15,0)) as customer_order_number
from exp_customer_order_num
